// === Tab: mySketch ===
// Translated to p5.js fork: oggy  https://openprocessing.org/sketch/555063

const gridSize = 55;
const dotSpacing = 8;
const influenceRadius = 50;
const maxDistortion = 15;

let dots = [];  

function setup() {
  createCanvas(600, 600);
  background(200);
  stroke(256);

  // center grid
  const offset = (width - gridSize * dotSpacing) / 2;

  // initialize dots
  for (let i = 0; i < gridSize; i++) {
    dots[i] = [];
    for (let j = 0; j < gridSize; j++) {
      dots[i][j] = new Dot(i * dotSpacing + offset, j * dotSpacing + offset);
    }
  }
}

function draw() {
  fill(0);
  rect(0, 0, width, height);

  const mousePosition = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

  // update dots
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      dots[i][j].update(mousePosition);
    }
  }
}

class Dot {
  constructor(x, y) {
    this.position = createVector(x, y);
    this.originalPosition = this.position.copy();
    this.velocity = createVector(0, 0);
  }

  update(mousePos) {
    // vector from original position to mouse
    let vecToMouse = this.originalPosition.copy();
    vecToMouse.sub(mousePos);

    const distanceToMouse = vecToMouse.mag();

    // mapping distance to phase value for sine distortion
    const phase = map(distanceToMouse, 0, influenceRadius, 0, PI);

    // normalize and scale vector for distortion
    vecToMouse.normalize();
    vecToMouse.mult(maxDistortion * sin(phase));

    // stroke weight based on distance
    let strokeWidth;
    if (distanceToMouse < influenceRadius) {
      strokeWidth = 1 + 10 * abs(cos(phase / 2));
    } else {
      strokeWidth = map(min(distanceToMouse, width), 0, width, 5, 0.1);
    }

    // set target position with distortion
    const targetPosition = createVector(
      this.originalPosition.x + vecToMouse.x,
      this.originalPosition.y + vecToMouse.y
    );

    // current position to target
    let attractionVector = this.position.copy();
    attractionVector.sub(targetPosition);

    // attraction force negative for pull target
    const attractionStrength = map(
      mousePos.dist(this.position),
      0,
      2 * width,
      0.1,
      0.01
    );
    attractionVector.mult(-attractionStrength);

    this.velocity.add(attractionVector);
    this.velocity.mult(0.87);  // friction/damping

    this.position.add(this.velocity);

    strokeWeight(strokeWidth);
    point(this.position.x, this.position.y);
  }
}

